
const root=document.getElementById('areiaamigos-view');
if(root){
const materials=['Areia Fina Branca','Areia Fina Amarelinha','Areia Média','Aterro','Areia'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const br=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let records=[],photo='',active='recebimento',selected=null,uncertainFields=[];
const today=()=>new Date().toLocaleDateString('en-CA');
const upload=()=>document.getElementById('aa-file').click();
root.innerHTML='<div class="aa-head"><div><h2>Areia Amigos</h2><p>Controle de recebimento de cargas</p></div><button id="aa-new">＋ Novo recebimento</button></div><div class="aa-tabs"><button data-aa-tab="recebimento" class="active">Recebimento</button><button data-aa-tab="historico">Histórico</button><button data-aa-tab="relatorios">Relatórios</button></div><div id="aa-body"></div><input type="file" id="aa-file" accept="image/jpeg,image/png,image/webp" hidden>';
const fields=()=>['receipt','date','time','client','plate','total',...materials.map((_,i)=>'qty'+i)];
const defaults=()=>({receipt:'',date:today(),time:new Date().toTimeString().slice(0,5),client:'',plate:'',total:'',quantities:[0,0,0,0,0]});
let draft=defaults();
function setTab(tab){active=tab;root.querySelectorAll('[data-aa-tab]').forEach(b=>b.classList.toggle('active',b.dataset.aaTab===tab));draw();}
function collect(){const form=root.querySelector('#aa-form');if(!form)return;const d=new FormData(form);draft={receipt:d.get('receipt')||'',date:d.get('date')||'',time:d.get('time')||'',client:d.get('client')||'',plate:d.get('plate')||'',total:d.get('total')||'',quantities:materials.map((_,i)=>d.get('qty'+i)||'')};}
function input(name,label,type='text',value=''){const warn=uncertainFields.includes(name);return '<label class="'+(warn?'aa-uncertain':'')+'">'+label+(warn?' <span class="aa-review">⚠ Conferir</span>':'')+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(name==='receipt'||name==='date'?'required':'')+'></label>';}
function receiptPanel(){const img=photo?'<img class="aa-receipt-img" src="'+photo+'" alt="Imagem do recibo anexado">':'<div class="aa-drop" id="aa-drop">☁<strong>Arraste a imagem do recibo aqui</strong><small>ou clique para selecionar JPG, PNG ou WEBP</small></div>';return '<div class="aa-columns"><section class="aa-card"><h3>1. Imagem do recibo</h3><div class="aa-image-box">'+img+'</div><div class="aa-actions"><button id="aa-upload">📎 '+(photo?'Trocar imagem':'Selecionar imagem')+'</button><button id="aa-zoom" '+(!photo?'disabled':'')+'>Ampliar</button><button id="aa-remove" '+(!photo?'disabled':'')+'>Remover</button></div></section><section class="aa-card"><h3>2. Informações extraídas da imagem</h3><div class="aa-info" id="aa-info">Anexe um recibo e use “Extrair dados”. Confira as informações antes de salvar.</div><div class="aa-actions"><button id="aa-extract" '+(!photo?'disabled':'')+'>↻ Extrair dados (OCR)</button></div><form id="aa-form"><div class="aa-fields">'+input('receipt','Nº do recibo','text',draft.receipt)+input('date','Data','date',draft.date)+input('time','Hora','time',draft.time)+'</div>'+input('client','Cliente','text',draft.client)+input('plate','Placa','text',draft.plate)+'<h4>Itens da carga (m³)</h4><div class="aa-items">'+materials.map((m,i)=>input('qty'+i,m,'number',draft.quantities[i])).join('')+'</div>'+input('total','Valor total (R$)','text',draft.total)+'<div class="aa-actions aa-right"><button type="button" id="aa-clear">Limpar</button><button class="aa-primary" type="submit">▣ Salvar recebimento</button></div></form></section><section class="aa-card"><h3>3. Pré-visualização</h3><div class="aa-preview">'+(photo?'<img src="'+photo+'" alt="Prévia do recibo">':'Nenhuma imagem anexada')+'</div><h4>Detalhes do recebimento</h4><div class="aa-details" id="aa-details"></div><div class="aa-share-grid"><button type="button" class="aa-share-card aa-share-wa" id="aa-share-whatsapp"><span class="aa-share-icon" aria-hidden="true">☎</span><strong>Enviar pelo<br>WhatsApp</strong><small>Compartilhar recibo com imagem e informações</small><span class="aa-share-action">➤ Compartilhar</span></button><button type="button" class="aa-share-card aa-share-mail" id="aa-share-email"><span class="aa-share-icon" aria-hidden="true">✉</span><strong>Enviar por<br>E-mail</strong><small>Enviar recibo com imagem e informações</small><span class="aa-share-action">✉ Enviar e-mail</span></button></div></section></div>';}
function history(){return '<section class="aa-card"><h3>Histórico de recebimentos</h3><div class="aa-filters"><input id="aa-search" placeholder="Buscar cliente, placa ou recibo"><select id="aa-material"><option value="">Todos os materiais</option>'+materials.map(m=>'<option>'+esc(m)+'</option>').join('')+'</select><input id="aa-from" type="date" aria-label="Data inicial"><input id="aa-to" type="date" aria-label="Data final"><button id="aa-export">Exportar CSV</button></div><div class="table-scroll"><table class="aa-table"><thead><tr><th>Data</th><th>Hora</th><th>Recibo</th><th>Cliente</th><th>Placa</th>'+materials.map(m=>'<th>'+m+'</th>').join('')+'<th>Total (R$)</th><th>Imagem</th><th>Excluir</th></tr></thead><tbody id="aa-rows"></tbody></table></div></section>';}
function draw(){const body=root.querySelector('#aa-body');body.innerHTML=(active==='recebimento'?receiptPanel():active==='historico'?history():'<section class="aa-card"><h3>Relatórios de recebimento</h3><div id="aa-summary"></div></section>')+(active==='recebimento'?history():'');if(active==='recebimento'){root.querySelector('#aa-upload').onclick=upload;root.querySelector('#aa-drop')?.addEventListener('click',upload);root.querySelector('#aa-remove').onclick=()=>{photo='';uncertainFields=[];draw()};root.querySelector('#aa-zoom').onclick=()=>{const w=window.open('');if(w)w.document.write('<img src="'+photo+'" style="max-width:100%;height:auto">')};root.querySelector('#aa-clear').onclick=()=>{draft=defaults();photo='';selected=null;uncertainFields=[];draw()};root.querySelector('#aa-share-whatsapp').onclick=()=>shareReceipt('whatsapp');root.querySelector('#aa-share-email').onclick=()=>shareReceipt('email');root.querySelector('#aa-extract').onclick=extract;root.querySelector('#aa-form').onsubmit=save;root.querySelector('#aa-form').oninput=e=>{collect();if(e.target?.name){uncertainFields=uncertainFields.filter(x=>x!==e.target.name);const label=e.target.closest('label');label?.classList.remove('aa-uncertain');label?.querySelector('.aa-review')?.remove()}details()};details()}if(active==='relatorios'){root.querySelector('#aa-summary').innerHTML='<p>Total de recebimentos: <strong>'+records.length+'</strong></p><p>Volume recebido: <strong>'+br(records.reduce((a,r)=>a+(r.quantities||[]).reduce((x,y)=>x+Number(y||0),0),0))+' m³</strong></p><p>Valor total: <strong>R$ '+br(records.reduce((a,r)=>a+Number(r.total||0),0))+'</strong></p>'+materials.map((m,i)=>'<p>'+m+': <strong>'+br(records.reduce((a,r)=>a+Number(r.quantities?.[i]||0),0))+' m³</strong></p>').join('')}renderRows();}
function shareText(){
 const date=draft.date?draft.date.split('-').reverse().join('/'):'—';
 const qty=materials.map((m,i)=>({name:m,value:Number(draft.quantities?.[i]||0)})).filter(x=>x.value>0).map(x=>x.name+': '+x.value+' m³').join('\n')||'Não informado';
 return 'RECEBIMENTO DE AREIA — COLAFIX\nRecibo: '+(draft.receipt||'—')+'\nData: '+date+'\nHora: '+(draft.time||'—')+'\nCliente: '+(draft.client||'—')+'\nPlaca: '+(draft.plate||'—')+'\nMateriais:\n'+qty+'\nValor total: R$ '+(draft.total||'0,00');
}
function downloadReceiptImage(){
 if(!photo)return;
 const link=document.createElement('a');link.href=photo;link.download='recibo-'+(draft.receipt||'areia-amigos')+'.'+(photo.startsWith('data:image/png')?'png':photo.startsWith('data:image/webp')?'webp':'jpg');document.body.appendChild(link);link.click();link.remove();
}
async function shareReceipt(channel){
 collect();if(!photo)return alert('Anexe a imagem do recibo primeiro.');
 const message=shareText();
 if(navigator.share&&navigator.canShare){
  try{
   const response=await fetch(photo),blob=await response.blob();
   const extension=blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg';
   const file=new File([blob],'recibo-'+(draft.receipt||'areia-amigos')+'.'+extension,{type:blob.type||'image/jpeg'});
   if(navigator.canShare({files:[file]})){
    await navigator.share({title:'Recibo '+(draft.receipt||''),text:message,files:[file]});
    return;
   }
  }catch(err){if(err.name==='AbortError')return}
 }
 downloadReceiptImage();
 if(channel==='whatsapp')window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener');
 else window.location.href='mailto:?subject='+encodeURIComponent('Recibo Areia Amigos nº '+(draft.receipt||''))+'&body='+encodeURIComponent(message+'\n\nAnexe a imagem do recibo baixada pelo navegador.');
 alert('A foto foi baixada. Anexe o arquivo do recibo na conversa ou no e-mail antes de enviar.');
}
function details(){const el=root.querySelector('#aa-details');if(el)el.innerHTML='<p>Recibo: <strong>'+esc(draft.receipt||'—')+'</strong></p><p>Data: '+esc(draft.date||'—')+' · '+esc(draft.time||'—')+'</p><p>Cliente: '+esc(draft.client||'—')+'</p><p>Placa: '+esc(draft.plate||'—')+'</p><p>Valor: R$ '+esc(draft.total||'0,00')+'</p>';}
function renderRows(){const tbody=root.querySelector('#aa-rows');if(!tbody)return;const q=(root.querySelector('#aa-search')?.value||'').toLowerCase(),mat=root.querySelector('#aa-material')?.value||'',from=root.querySelector('#aa-from')?.value||'',to=root.querySelector('#aa-to')?.value||'';const list=records.filter(r=>(!q||[r.receipt,r.client,r.plate].some(v=>String(v||'').toLowerCase().includes(q)))&&(!mat||Number(r.quantities?.[materials.indexOf(mat)]||0)>0)&&(!from||r.date>=from)&&(!to||r.date<=to)).sort((a,b)=>{const na=Number(String(a.receipt||'').replace(/\D/g,'')),nb=Number(String(b.receipt||'').replace(/\D/g,''));return nb-na||String(b.receipt||'').localeCompare(String(a.receipt||''),'pt-BR',{numeric:true})});tbody.innerHTML=list.map(r=>'<tr><td>'+esc(r.date?.split('-').reverse().join('/'))+'</td><td>'+esc(r.time)+'</td><td>'+esc(r.receipt)+'</td><td>'+esc(r.client)+'</td><td>'+esc(r.plate)+'</td>'+(r.quantities||[]).map(n=>'<td>'+(Number(n)?esc(n):'—')+'</td>').join('')+'<td>'+br(r.total)+'</td><td><button data-aa-open="'+esc(r.id)+'">🖼️ Ver</button></td><td><button type="button" data-aa-delete="'+esc(r.id)+'" title="Excluir recibo" aria-label="Excluir recibo '+esc(r.receipt)+'">🗑️</button></td></tr>').join('')||'<tr><td colspan="12">Nenhum recebimento encontrado.</td></tr>';tbody.querySelectorAll('[data-aa-open]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.aaOpen);if(!r)return;selected=r.id;draft={...r};photo=r.image||'';uncertainFields=[];setTab('recebimento')});tbody.querySelectorAll('[data-aa-delete]').forEach(b=>b.onclick=async()=>{const r=records.find(x=>x.id===b.dataset.aaDelete);if(!r)return;if(!confirm('Excluir definitivamente o recibo nº '+r.receipt+'? A imagem e os dados deste registro também serão excluídos.'))return;b.disabled=true;try{const response=await fetch('/api/areia-amigos/'+encodeURIComponent(r.id),{method:'DELETE'});const j=await response.json();if(!response.ok)throw Error(j.error||'Falha ao excluir');records=j.records;if(selected===r.id){selected=null;draft=defaults();photo='';uncertainFields=[]}renderRows();alert('Recibo nº '+r.receipt+' excluído.')}catch(e){b.disabled=false;alert(e.message)}});}
async function load(){try{const r=await fetch('/api/areia-amigos');if(!r.ok)throw Error('Falha ao carregar');records=(await r.json()).records||[];draw()}catch(e){root.querySelector('#aa-body').innerHTML='<p>Erro ao carregar recebimentos: '+esc(e.message)+'</p>'}}
async function save(e){e.preventDefault();collect();const duplicate=records.find(r=>String(r.receipt||'').trim()===String(draft.receipt||'').trim()&&String(r.id)!==String(selected||''));if(duplicate)return alert('⚠ Recibo nº '+draft.receipt+' já está cadastrado no histórico. Não é permitido cadastrar novamente.');if(!photo)return alert('Anexe a imagem do recibo antes de salvar.');const amount=String(draft.total).replace(/\./g,'').replace(',','.');const entry={...draft,id:selected||crypto.randomUUID(),total:Number(amount)||0,quantities:draft.quantities.map(x=>Number(x)||0),image:photo};try{const r=await fetch('/api/areia-amigos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)});const j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível salvar');records=j.records;draft=defaults();photo='';selected=null;setTab('historico');alert('Recebimento salvo com imagem!')}catch(err){alert(err.message)}}
function fileToData(file){return new Promise((resolve,reject)=>{if(file.size>5*1024*1024)return reject(Error('Imagem acima de 5 MB. Reduza a foto.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
root.querySelector('#aa-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{collect();photo=await fileToData(file);draw()}catch(err){alert(err.message)}e.target.value=''};
root.querySelectorAll('[data-aa-tab]').forEach(b=>b.onclick=()=>{collect();setTab(b.dataset.aaTab)});root.querySelector('#aa-new').onclick=()=>{draft=defaults();photo='';selected=null;setTab('recebimento')};
root.addEventListener('input',e=>{if(['aa-search','aa-material','aa-from','aa-to'].includes(e.target.id))renderRows()});
root.addEventListener('click',e=>{if(e.target.id!=='aa-export')return;const head=['Data','Hora','Recibo','Cliente','Placa',...materials,'Total'];const lines=records.map(r=>[r.date,r.time,r.receipt,r.client,r.plate,...r.quantities,r.total]);const csv=[head,...lines].map(a=>a.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='areia-amigos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
async function extract(){
 collect();const info=root.querySelector('#aa-info');info.textContent='IA analisando a escrita do recibo...';
 try{
  const response=await fetch('/api/areia-amigos/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:photo})});
  const result=await response.json();if(!response.ok)throw Error(result.error||'Falha na leitura');
  const d=result.data||{};if(d.receipt)draft.receipt=d.receipt;if(d.date)draft.date=d.date;if(d.time)draft.time=d.time;if(d.client)draft.client=d.client;if(d.plate)draft.plate=d.plate;
  if(d.total!=null&&Number.isFinite(d.total))draft.total=d.total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(Array.isArray(d.quantities))d.quantities.forEach((v,i)=>{if(v!=null&&Number.isFinite(v)&&v>=0)draft.quantities[i]=v});
  uncertainFields=[...new Set([...(d.uncertain_fields||[]),...(['receipt','date','time','client','plate','total'].filter(k=>d[k]==null)),...(Array.isArray(d.quantities)?d.quantities.map((v,i)=>v==null?'qty'+i:null).filter(Boolean):[])])];
  draw();root.querySelector('#aa-info').textContent='Leitura por IA concluída. Confira os dados manuscritos antes de salvar.'+(uncertainFields.length?' Campos em amarelo precisam de conferência.':'')+(d.warnings?.length?' Observações: '+d.warnings.join('; '):'');
 }catch(e){info.textContent='Não foi possível ler com IA: '+e.message+'. Confira a configuração e preencha manualmente.'}
}
load();
}
